import itertools
vals={'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
# generate canonical roman numerals up to 3999
# We'll implement int->roman and then check for length 3 and palindrome.

def int_to_roman(n):
    if not (0<n<4000):
        raise ValueError
    numerals=[
        (1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')
    ]
    res=''
    for v,s in numerals:
        while n>=v:
            res+=s
            n-=v
    return res

pals=[]
for n in range(1,4000):
    r=int_to_roman(n)
    if len(r)==3 and r==r[::-1]:
        pals.append((n,r))

print(len(pals), pals[:50])
print('sum', sum(n for n,_ in pals))
